// ===== ERROR CATCHER =====
// Captures full error context from the failed node
// Author: Rana Ahmad — github.com/Ranahmad1

const item = $input.first();
const error = item.json.error || {};
const statusCode = error.statusCode || error.httpCode || item.json.statusCode || 0;
const errorMessage = error.message || item.json.message || JSON.stringify(error);

const errorContext = {
  timestamp: new Date().toISOString(),
  execution_id: $execution.id,
  workflow_id: $workflow.id,
  workflow_name: $workflow.name,
  failed_node: item.json.failed_node || 'HTTP Request Node',
  error_raw: error,
  error_message: errorMessage,
  status_code: statusCode,
  retry_count: item.json.retry_count || 0,
  original_input: item.json.original_input || item.json
};

console.log('ERROR_CAUGHT:', JSON.stringify({ node: errorContext.failed_node, status: errorContext.status_code, msg: errorContext.error_message }));

return [{ json: errorContext }];

// ===== ROOT CAUSE ANALYZER =====
// Classifies error type and determines risk level
// Author: Rana Ahmad — github.com/Ranahmad1

const ctx = $input.first().json;
const msg = (ctx.error_message || '').toLowerCase();
const code = parseInt(ctx.status_code) || 0;

let errorType = 'UNKNOWN';
let rootCause = 'Unknown error occurred';
let riskLevel = 'LOW';

if (code === 429 || msg.includes('rate limit') || msg.includes('too many requests')) {
  errorType = 'RATE_LIMIT';
  rootCause = 'API rate limit exceeded — too many requests in a short window';
  riskLevel = 'LOW';
} else if (code >= 500 && code < 600) {
  errorType = 'SERVER_ERROR';
  rootCause = `Upstream server error (HTTP ${code}) — transient server-side failure`;
  riskLevel = 'LOW';
} else if (code === 401 || code === 403) {
  errorType = 'AUTH_ERROR';
  rootCause = `Authentication failed (HTTP ${code}) — credentials invalid or expired`;
  riskLevel = 'HIGH';
} else if (code === 404) {
  errorType = 'NOT_FOUND';
  rootCause = 'Resource not found — endpoint or record may have been removed';
  riskLevel = 'LOW';
} else if (msg.includes('etimedout') || msg.includes('timeout') || msg.includes('econnaborted') || code === 408) {
  errorType = 'TIMEOUT';
  rootCause = 'Request timed out — network latency or slow server response';
  riskLevel = 'LOW';
} else if (msg.includes('econnrefused') || msg.includes('connection refused')) {
  errorType = 'CONNECTION_REFUSED';
  rootCause = 'Connection refused — target service is down or unreachable';
  riskLevel = 'LOW';
} else if (msg.includes('enotfound') || msg.includes('dns')) {
  errorType = 'DNS_ERROR';
  rootCause = 'DNS resolution failed — hostname cannot be resolved';
  riskLevel = 'LOW';
} else if (msg.includes('invalid') || msg.includes('null') || msg.includes('undefined') || msg.includes('cannot read')) {
  errorType = 'INVALID_DATA';
  rootCause = 'Invalid or null data received — schema mismatch or missing required fields';
  riskLevel = 'LOW';
} else if (code >= 400 && code < 500) {
  errorType = 'CLIENT_ERROR';
  rootCause = `Client-side error (HTTP ${code}) — bad request format or missing parameters`;
  riskLevel = 'MEDIUM';
}

console.log('ROOT_CAUSE:', JSON.stringify({ type: errorType, risk: riskLevel, cause: rootCause }));

return [{ json: { ...ctx, error_type: errorType, root_cause: rootCause, risk_level: riskLevel } }];

// ===== STRATEGY GENERATOR =====
// Generates a specific, parameterized recovery strategy
// Author: Rana Ahmad — github.com/Ranahmad1

const ctx = $input.first().json;
const BASE_DELAY = 1000;
const MULTIPLIER = 2;
const MAX_DELAY = 30000;
const MAX_RETRIES = 3;

const retryCount = ctx.retry_count || 0;
const delay = Math.min(BASE_DELAY * Math.pow(MULTIPLIER, retryCount), MAX_DELAY);
const jitter = Math.floor(Math.random() * 500);
const delayWithJitter = delay + jitter;

let strategy = {
  type: 'HUMAN_ESCALATION',
  can_auto_recover: false,
  retry_after_ms: 0,
  max_retries: MAX_RETRIES,
  current_attempt: retryCount + 1,
  action: 'Escalate to human — no safe automatic recovery available',
  parameters: {}
};

switch (ctx.error_type) {
  case 'RATE_LIMIT':
    strategy = {
      type: 'EXPONENTIAL_BACKOFF',
      can_auto_recover: retryCount < MAX_RETRIES,
      retry_after_ms: delayWithJitter,
      max_retries: MAX_RETRIES,
      current_attempt: retryCount + 1,
      action: `Wait ${delayWithJitter}ms then retry (exponential backoff, attempt ${retryCount + 1}/${MAX_RETRIES})`,
      parameters: { delay_ms: delayWithJitter, reduce_concurrency: true }
    };
    break;

  case 'SERVER_ERROR':
    strategy = {
      type: 'RETRY_WITH_DELAY',
      can_auto_recover: retryCount < MAX_RETRIES,
      retry_after_ms: delayWithJitter,
      max_retries: MAX_RETRIES,
      current_attempt: retryCount + 1,
      action: `Wait ${delayWithJitter}ms then retry — server may have recovered`,
      parameters: { delay_ms: delayWithJitter }
    };
    break;

  case 'TIMEOUT':
    strategy = {
      type: 'RETRY_WITH_INCREASED_TIMEOUT',
      can_auto_recover: retryCount < MAX_RETRIES,
      retry_after_ms: 2000,
      max_retries: MAX_RETRIES,
      current_attempt: retryCount + 1,
      action: 'Retry with 2x timeout limit applied',
      parameters: { new_timeout_ms: 20000, delay_ms: 2000 }
    };
    break;

  case 'CONNECTION_REFUSED':
    strategy = {
      type: 'RETRY_AFTER_LONG_WAIT',
      can_auto_recover: retryCount < 2,
      retry_after_ms: 30000,
      max_retries: 2,
      current_attempt: retryCount + 1,
      action: 'Wait 30 seconds for service to come back online, then retry',
      parameters: { delay_ms: 30000 }
    };
    break;

  case 'INVALID_DATA':
    strategy = {
      type: 'USE_FALLBACK_DATA',
      can_auto_recover: true,
      retry_after_ms: 0,
      max_retries: 0,
      current_attempt: 1,
      action: 'Sanitize input data and apply fallback values for null/invalid fields',
      parameters: { sanitize: true, use_defaults: true }
    };
    break;

  case 'NOT_FOUND':
    strategy = {
      type: 'LOG_AND_SKIP',
      can_auto_recover: true,
      retry_after_ms: 0,
      max_retries: 0,
      current_attempt: 1,
      action: 'Log the missing resource and skip — continue processing remaining items',
      parameters: { skip: true }
    };
    break;

  case 'DNS_ERROR':
    strategy = {
      type: 'RETRY_WITH_DELAY',
      can_auto_recover: retryCount < 2,
      retry_after_ms: 5000,
      max_retries: 2,
      current_attempt: retryCount + 1,
      action: 'Wait 5s for DNS to propagate, then retry',
      parameters: { delay_ms: 5000 }
    };
    break;

  case 'AUTH_ERROR':
  case 'CLIENT_ERROR':
  default:
    // Keep default HUMAN_ESCALATION strategy
    break;
}

console.log('STRATEGY:', JSON.stringify({ type: strategy.type, canRecover: strategy.can_auto_recover, delay: strategy.retry_after_ms }));

return [{ json: { ...ctx, recovery_strategy: strategy } }];

// ===== HUMAN ESCALATION =====
// Builds alert payload and logs for human review
// Author: Rana Ahmad — github.com/Ranahmad1

const ctx = $input.first().json;

const alertPayload = {
  alert_type: 'WORKFLOW_REQUIRES_HUMAN_APPROVAL',
  timestamp: new Date().toISOString(),
  workflow: ctx.workflow_name,
  failed_node: ctx.failed_node,
  error_type: ctx.error_type,
  root_cause: ctx.root_cause,
  risk_level: ctx.risk_level,
  proposed_strategy: ctx.recovery_strategy?.action,
  retry_count: ctx.retry_count,
  message: `⚠️ HUMAN APPROVAL REQUIRED\n\nWorkflow: ${ctx.workflow_name}\nNode: ${ctx.failed_node}\nError: ${ctx.error_type}\nCause: ${ctx.root_cause}\nRisk Level: ${ctx.risk_level}\nAttempts: ${ctx.retry_count}\nProposed Fix: ${ctx.recovery_strategy?.action}\n\nPlease review and take action.`,
  execution_id: ctx.execution_id
};

console.log('HUMAN_ESCALATION_REQUIRED:', JSON.stringify(alertPayload, null, 2));

// Production: Add HTTP Request node after this to POST to ALERT_WEBHOOK_URL
// e.g. Slack, PagerDuty, email, MS Teams

return [{ json: { ...ctx, escalation: alertPayload, status: 'AWAITING_HUMAN_APPROVAL' } }];

// ===== RETRY ENGINE =====
// Prepares retry payload with modified parameters
// Author: Rana Ahmad — github.com/Ranahmad1

const ctx = $input.first().json;
const strategy = ctx.recovery_strategy;

if (!strategy.can_auto_recover) {
  return [{ json: {
    ...ctx,
    status: 'ESCALATED',
    outcome: 'Max retries reached or unsafe — escalated to human',
    logged_at: new Date().toISOString()
  }}];
}

const retryPayload = {
  ...ctx,
  retry_count: (ctx.retry_count || 0) + 1,
  strategy_applied: strategy.type,
  retry_at: new Date(Date.now() + strategy.retry_after_ms).toISOString(),
  status: 'RETRYING',
  retry_config: {
    url: ctx.original_input?.target_url || 'https://httpstat.us/200',
    timeout: strategy.parameters?.new_timeout_ms || 10000,
    delay_ms: strategy.retry_after_ms
  }
};

console.log('RETRY_PREPARED:', JSON.stringify({ attempt: retryPayload.retry_count, delay: strategy.retry_after_ms, strategy: strategy.type }));

return [{ json: retryPayload }];

// ===== EXECUTION LOGGER =====
// Writes a structured log entry for every recovery event
// Author: Rana Ahmad — github.com/Ranahmad1

const ctx = $input.first().json;

const logEntry = {
  log_id: `log_${Date.now()}_${Math.random().toString(36).substr(2, 6)}`,
  timestamp: new Date().toISOString(),
  workflow_id: ctx.workflow_id,
  workflow_name: ctx.workflow_name,
  execution_id: ctx.execution_id,
  failed_node: ctx.failed_node,
  error_type: ctx.error_type,
  error_message: ctx.error_message,
  status_code: ctx.status_code,
  root_cause: ctx.root_cause,
  risk_level: ctx.risk_level,
  recovery_strategy: ctx.recovery_strategy?.type || ctx.strategy_applied,
  strategy_action: ctx.recovery_strategy?.action,
  retry_attempt: ctx.retry_count || 0,
  delay_applied_ms: ctx.recovery_strategy?.retry_after_ms || 0,
  outcome: ctx.status || 'COMPLETED',
  escalated_to_human: ctx.status === 'AWAITING_HUMAN_APPROVAL' || ctx.status === 'ESCALATED',
  total_recovery_time_ms: Date.now() - new Date(ctx.timestamp || Date.now()).getTime()
};

console.log('RECOVERY_LOG_ENTRY:', JSON.stringify(logEntry, null, 2));

// Production integrations:
// - Write to Postgres/MySQL via Database node
// - Send to Datadog / Splunk via HTTP Request
// - Append to Google Sheets
// - Store in n8n static data

return [{ json: logEntry }];

// ===== SUCCESS HANDLER =====
// Handles the happy path — no error
const ctx = $input.first().json;
return [{ json: {
  status: 'SUCCESS',
  message: 'Workflow completed successfully — no errors detected',
  timestamp: new Date().toISOString(),
  data: ctx
}}];
